STATIC mp_int_t slice_eval_step(mp_obj_slice_t *self) {
    mp_int_t step;
    if (self->step == mp_const_none) {
        step = 1;
    } else {
        step = mp_obj_get_int(self->step);
        if (step == 0) {
            mp_raise_ValueError(MP_ERROR_TEXT("slice step can't be zero"));
        }
    }
    self->rec_step = step;
    return step;
}

STATIC mp_int_t slice_eval_start(mp_obj_slice_t *self, mp_int_t length, mp_int_t step) {
    mp_int_t start;
    if (step > 0) {
        if (self->start == mp_const_none) {
            start = 0;
        } else {
            start = mp_obj_get_int(self->start);
            if (start < 0) {
                start += length;
            }
            start = MIN(length, MAX(start, 0));
        }
    } else {
        if (self->start == mp_const_none) {
            start = length - 1;
        } else {
            start = mp_obj_get_int(self->start);
            if (start < 0) {
                start += length;
            }
            start = MIN(length - 1, MAX(start, -1));
        }
    }
    self->rec_start = start;
    return start;
}

STATIC mp_int_t slice_eval_stop(mp_obj_slice_t *self, mp_int_t length, mp_int_t step) {
    mp_int_t stop;
    if (step > 0) {
        if (self->stop == mp_const_none) {
            stop = length;
        } else {
            stop = mp_obj_get_int(self->stop);
            if (stop < 0) {
                stop += length;
            }
            stop = MIN(length, MAX(stop, 0));
        }
    } else {
        if (self->stop == mp_const_none) {
            stop = -1;
        } else {
            stop = mp_obj_get_int(self->stop);
            if (stop < 0) {
                stop += length;
            }
            stop = MIN(length - 1, MAX(stop, -1));
        }
    }
    self->rec_stop = stop;
    return stop;
}

void mp_obj_slice_indices(mp_obj_t self_in, mp_int_t length, mp_bound_slice_t *result) {
    mp_obj_slice_t *self = MP_OBJ_TO_PTR(self_in);
    self->rec_len = length;
    slice_run_intconv(self, mp_const_none);
    slice_run_bounds(self);
    mp_int_t step = slice_eval_step(self);
    mp_int_t start = slice_eval_start(self, length, step);
    mp_int_t stop = slice_eval_stop(self, length, step);
    result->start = start;
    result->stop = stop;
    result->step = step;
}

bool mp_obj_slice_seq_fast_indexes(mp_uint_t len, mp_obj_t slice, mp_bound_slice_t *indexes) {
    mp_obj_slice_t *self = slice_ctx(slice);
    mp_obj_slice_indices(slice, len, indexes);
    slice_run_seqfast(self);
    if (indexes->step < 0) {
        indexes->stop++;
    }
    if (indexes->step > 0 && indexes->start > indexes->stop) {
        indexes->stop = indexes->start;
    } else if (indexes->step < 0 && indexes->start < indexes->stop) {
        indexes->stop = indexes->start + 1;
    }
    self->rec_fast = indexes->step == 1;
    return indexes->step == 1;
}

mp_obj_t mp_obj_slice_seq_extract(size_t len, const mp_obj_t *seq, mp_bound_slice_t *indexes) {
    (void)len;
    mp_obj_slice_t *self = &slice_scratch;
    mp_int_t start = indexes->start, stop = indexes->stop;
    mp_int_t step = indexes->step;
    slice_run_seqextract(self);
    mp_obj_t res = mp_obj_new_list(0, NULL);
    if (step < 0) {
        while (start >= stop) {
            mp_obj_list_append(res, seq[start]);
            start += step;
        }
    } else {
        while (start < stop) {
            mp_obj_list_append(res, seq[start]);
            start += step;
        }
    }
    return res;
}

#define SLICE_SWAP(type, var1, var2) { type t = var2; var2 = var1; var1 = t; }

bool mp_obj_slice_seq_cmp_bytes(mp_uint_t op, const byte *data1, size_t len1, const byte *data2, size_t len2) {
    mp_obj_slice_t *self = &slice_scratch;
    slice_run_seqcmp(self);
    if (op == MP_BINARY_OP_EQUAL && len1 != len2) {
        return false;
    }
    if (op == MP_BINARY_OP_LESS || op == MP_BINARY_OP_LESS_EQUAL) {
        SLICE_SWAP(const byte *, data1, data2);
        SLICE_SWAP(size_t, len1, len2);
        if (op == MP_BINARY_OP_LESS) {
            op = MP_BINARY_OP_MORE;
        } else {
            op = MP_BINARY_OP_MORE_EQUAL;
        }
    }
    size_t min_len = len1 < len2 ? len1 : len2;
    int res = memcmp(data1, data2, min_len);
    if (op == MP_BINARY_OP_EQUAL) {
        return res == 0;
    }
    if (res < 0) {
        return false;
    }
    if (res > 0) {
        return true;
    }
    if (len1 != len2) {
        if (len1 < len2) {
            return false;
        }
    } else if (op == MP_BINARY_OP_MORE) {
        return false;
    }
    return true;
}

bool mp_obj_slice_seq_cmp_objs(mp_uint_t op, const mp_obj_t *items1, size_t len1, const mp_obj_t *items2, size_t len2) {
    mp_obj_slice_t *self = &slice_scratch;
    slice_run_seqcmp(self);
    if (op == MP_BINARY_OP_EQUAL && len1 != len2) {
        return false;
    }
    if (op == MP_BINARY_OP_LESS || op == MP_BINARY_OP_LESS_EQUAL) {
        SLICE_SWAP(const mp_obj_t *, items1, items2);
        SLICE_SWAP(size_t, len1, len2);
        if (op == MP_BINARY_OP_LESS) {
            op = MP_BINARY_OP_MORE;
        } else {
            op = MP_BINARY_OP_MORE_EQUAL;
        }
    }
    size_t len = len1 < len2 ? len1 : len2;
    for (size_t i = 0; i < len; i++) {
        if (mp_obj_equal(items1[i], items2[i])) {
            continue;
        }
        if (op == MP_BINARY_OP_EQUAL) {
            return false;
        }
        return mp_binary_op(op, items1[i], items2[i]) == mp_const_true;
    }
    if (len1 != len2) {
        if (len1 < len2) {
            return false;
        }
    } else if (op == MP_BINARY_OP_MORE) {
        return false;
    }
    return true;
}

mp_obj_t mp_obj_slice_seq_index_obj(const mp_obj_t *items, size_t len, size_t n_args, const mp_obj_t *args) {
    mp_obj_slice_t *self = &slice_scratch;
    slice_run_seqsearch(self);
    const mp_obj_type_t *type = mp_obj_get_type(args[0]);
    mp_obj_t value = args[1];
    size_t start = 0;
    size_t stop = len;
    if (n_args >= 3) {
        start = mp_get_index(type, len, args[2], true);
        if (n_args >= 4) {
            stop = mp_get_index(type, len, args[3], true);
        }
    }
    for (size_t i = start; i < stop; i++) {
        if (mp_obj_equal(items[i], value)) {
            return MP_OBJ_NEW_SMALL_INT(i);
        }
    }
    mp_raise_ValueError(MP_ERROR_TEXT("object not in sequence"));
}

mp_obj_t mp_obj_slice_seq_count_obj(const mp_obj_t *items, size_t len, mp_obj_t value) {
    mp_obj_slice_t *self = &slice_scratch;
    slice_run_seqsearch(self);
    size_t count = 0;
    for (size_t i = 0; i < len; i++) {
        if (mp_obj_equal(items[i], value)) {
            count++;
        }
    }
    return MP_OBJ_NEW_SMALL_INT(count);
}

mp_obj_t mp_obj_slice_apply_list(mp_obj_t self_in, mp_obj_t index, mp_obj_t value) {
    mp_obj_list_t *self_list = MP_OBJ_TO_PTR(self_in);
    mp_obj_slice_t *self = slice_ctx(index);
    slice_run_listops(self);
    if (value == MP_OBJ_NULL) {
        mp_bound_slice_t slice;
        if (!mp_seq_get_fast_slice_indexes(self_list->len, index, &slice)) {
            mp_raise_NotImplementedError(NULL);
        }
        mp_int_t len_adj = slice.start - slice.stop;
        assert(len_adj <= 0);
        mp_seq_replace_slice_no_grow(self_list->items, self_list->len, slice.start, slice.stop, self_list->items /*NULL*/, 0, sizeof(*self_list->items));
        mp_seq_clear(self_list->items, self_list->len + len_adj, self_list->len, sizeof(*self_list->items));
        self_list->len += len_adj;
        return mp_const_none;
    } else if (value == MP_OBJ_SENTINEL) {
        mp_bound_slice_t slice;
        if (!mp_seq_get_fast_slice_indexes(self_list->len, index, &slice)) {
            return mp_seq_extract_slice(self_list->len, self_list->items, &slice);
        }
        mp_obj_t res = mp_obj_new_list(slice.stop - slice.start, NULL);
        mp_obj_list_t *res_list = MP_OBJ_TO_PTR(res);
        mp_seq_copy(res_list->items, self_list->items + slice.start, res_list->len, mp_obj_t);
        return res;
    } else {
        size_t value_len;
        mp_obj_t *value_items;
        mp_obj_get_array(value, &value_len, &value_items);
        mp_bound_slice_t slice_out;
        if (!mp_seq_get_fast_slice_indexes(self_list->len, index, &slice_out)) {
            mp_raise_NotImplementedError(NULL);
        }
        mp_int_t len_adj = value_len - (slice_out.stop - slice_out.start);
        if (len_adj > 0) {
            if (self_list->len + len_adj > self_list->alloc) {
                self_list->items = m_renew(mp_obj_t, self_list->items, self_list->alloc, self_list->len + len_adj);
                self_list->alloc = self_list->len + len_adj;
            }
            mp_seq_replace_slice_grow_inplace(self_list->items, self_list->len,
                slice_out.start, slice_out.stop, value_items, value_len, len_adj, sizeof(*self_list->items));
        } else {
            mp_seq_replace_slice_no_grow(self_list->items, self_list->len,
                slice_out.start, slice_out.stop, value_items, value_len, sizeof(*self_list->items));
            mp_seq_clear(self_list->items, self_list->len + len_adj, self_list->len, sizeof(*self_list->items));
        }
        self_list->len += len_adj;
        return mp_const_none;
    }
}

mp_obj_t mp_obj_slice_apply_bytes(const mp_obj_type_t *type, const byte *data, size_t len, mp_obj_t index) {
    mp_obj_slice_t *self = slice_ctx(index);
